import type {
  ComponentBlueprint,
  ComponentBlueprintAttribute,
  ComponentBlueprintStyleHook,
  ComponentStyleTarget
} from '../blueprint/component-blueprint.js';
import { componentBlueprints } from '../blueprint/components/index.js';

export const GENERATED_COMPONENT_DIRECTORY = 'src/generated/components';

export interface GeneratedComponentArtifact {
  componentId: string;
  tagName: string;
  artifactFileName: string;
  source: string;
}

interface StyleTargetSelector {
  selector: string;
  target: ComponentStyleTarget;
}

const FILE_HEADER_LINES = [
  '// This file is generated by @prism/ui-core component blueprints.',
  '// Do not edit this file manually.',
  ''
];

function findAttribute(blueprint: ComponentBlueprint, attributeName: string): ComponentBlueprintAttribute {
  const attribute = blueprint.attributes.find((entry) => entry.name === attributeName);

  if (!attribute) {
    throw new Error(`Missing attribute "${attributeName}" on component blueprint "${blueprint.componentId}".`);
  }

  return attribute;
}

function enumValues(attribute: ComponentBlueprintAttribute): readonly string[] {
  if (attribute.type !== 'enum' || !attribute.enumValues || attribute.enumValues.length === 0) {
    throw new Error(`Attribute "${attribute.name}" must define enumValues.`);
  }

  return attribute.enumValues;
}

function enumDefault(attribute: ComponentBlueprintAttribute): string {
  if (attribute.type !== 'enum' || typeof attribute.defaultValue !== 'string') {
    throw new Error(`Attribute "${attribute.name}" must define a string defaultValue.`);
  }

  return attribute.defaultValue;
}

function renderArray(values: readonly string[]): string {
  return `[${values.map((value) => JSON.stringify(value)).join(', ')}]`;
}

function hookDeclaration(hook: ComponentBlueprintStyleHook): string {
  const fallback = hook.fallback ? `, ${hook.fallback}` : '';
  return `  ${hook.cssProperty}: var(${hook.cssVariable}${fallback});`;
}

function renderStyleHooks(
  blueprint: ComponentBlueprint,
  selectorMap: readonly StyleTargetSelector[]
): string {
  const blocks = selectorMap
    .map(({ selector, target }) => {
      const hooks = blueprint.styleHooks
        .filter((entry) => entry.target === target)
        .sort((left, right) => left.name.localeCompare(right.name));

      if (hooks.length === 0) {
        return '';
      }

      return [selector + ' {', ...hooks.map((hook) => hookDeclaration(hook)), '}'].join('\n');
    })
    .filter((entry) => entry.length > 0);

  return blocks.join('\n\n');
}

function buttonSource(blueprint: ComponentBlueprint): string {
  const variantAttribute = findAttribute(blueprint, 'variant');
  const sizeAttribute = findAttribute(blueprint, 'size');
  const typeAttribute = findAttribute(blueprint, 'type');

  const variants = enumValues(variantAttribute);
  const sizes = enumValues(sizeAttribute);
  const types = enumValues(typeAttribute);

  const defaultVariant = enumDefault(variantAttribute);
  const defaultSize = enumDefault(sizeAttribute);
  const defaultType = enumDefault(typeAttribute);

  const styleHooks = renderStyleHooks(blueprint, [
    { selector: ':host', target: 'host' },
    { selector: '.container', target: 'container' },
    { selector: '.control', target: 'control' },
    { selector: '.label', target: 'text' },
    { selector: '.icon-slot', target: 'icon' }
  ]);

  return [
    ...FILE_HEADER_LINES,
    'const PrismHTMLElement = globalThis.HTMLElement ?? class {};',
    `const BUTTON_VARIANTS = Object.freeze(${renderArray(variants)});`,
    `const BUTTON_SIZES = Object.freeze(${renderArray(sizes)});`,
    `const BUTTON_TYPES = Object.freeze(${renderArray(types)});`,
    `const DEFAULT_VARIANT = ${JSON.stringify(defaultVariant)};`,
    `const DEFAULT_SIZE = ${JSON.stringify(defaultSize)};`,
    `const DEFAULT_TYPE = ${JSON.stringify(defaultType)};`,
    '',
    `export const ${blueprint.className}Slots = Object.freeze(${renderArray(blueprint.slots.map((slot) => slot.name))});`,
    `export const ${blueprint.className}Parts = Object.freeze(${renderArray(blueprint.parts.map((part) => part.name))});`,
    '',
    `export class ${blueprint.className} extends PrismHTMLElement {`,
    `  static tagName = ${JSON.stringify(blueprint.tagName)};`,
    `  static observedAttributes = Object.freeze(${renderArray(
      blueprint.attributes.map((attribute) => attribute.name).sort((left, right) => left.localeCompare(right))
    )});`,
    '',
    '  #control = null;',
    '  #label = null;',
    '',
    '  constructor() {',
    '    super();',
    '    if (typeof this.attachShadow === "function" && !this.shadowRoot) {',
    '      this.attachShadow({ mode: "open" });',
    '    }',
    '  }',
    '',
    '  connectedCallback() {',
    '    this.#render();',
    '    this.#sync();',
    '  }',
    '',
    '  attributeChangedCallback() {',
    '    this.#sync();',
    '  }',
    '',
    '  #render() {',
    '    if (!this.shadowRoot || this.shadowRoot.childNodes.length > 0) {',
    '      return;',
    '    }',
    '',
    '    this.shadowRoot.innerHTML = `',
    '<style>',
    ':host {',
    '  display: inline-flex;',
    '  vertical-align: middle;',
    '}',
    '',
    '.container {',
    '  display: inline-flex;',
    '}',
    '',
    '.control {',
    '  align-items: center;',
    '  border: 1px solid transparent;',
    '  cursor: pointer;',
    '  display: inline-flex;',
    '  gap: 0.5rem;',
    '  justify-content: center;',
    '  min-height: 2.5rem;',
    '  min-width: 2.5rem;',
    '  padding-inline: 1rem;',
    '  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;',
    '}',
    '',
    '.control:focus-visible {',
    '  outline: 2px solid var(--prism-color-outline, #74777f);',
    '  outline-offset: 2px;',
    '}',
    '',
    '.control:disabled {',
    '  cursor: not-allowed;',
    '  opacity: 0.38;',
    '}',
    '',
    '.icon-slot {',
    '  display: inline-flex;',
    '  line-height: 1;',
    '}',
    '',
    '.label {',
    '  display: inline-flex;',
    '  text-align: center;',
    '}',
    '',
    styleHooks,
    '</style>',
    '<span class="container" part="container">',
    '  <button class="control" part="control" type="button">',
    '    <span class="icon-slot" part="leading-icon"><slot name="leading"></slot></span>',
    '    <span class="label" part="label"><slot></slot></span>',
    '    <span class="icon-slot" part="trailing-icon"><slot name="trailing"></slot></span>',
    '  </button>',
    '</span>',
    '`;',
    '',
    '    this.#control = this.shadowRoot.querySelector(".control");',
    '    this.#label = this.shadowRoot.querySelector(".label");',
    '  }',
    '',
    '  #sync() {',
    '    const control = this.#control;',
    '    const label = this.#label;',
    '',
    '    if (!control || !label) {',
    '      return;',
    '    }',
    '',
    '    const variant = this.getAttribute("variant");',
    '    const size = this.getAttribute("size");',
    '    const type = this.getAttribute("type");',
    '',
    '    const resolvedVariant = BUTTON_VARIANTS.includes(variant ?? "") ? variant : DEFAULT_VARIANT;',
    '    const resolvedSize = BUTTON_SIZES.includes(size ?? "") ? size : DEFAULT_SIZE;',
    '    const resolvedType = BUTTON_TYPES.includes(type ?? "") ? type : DEFAULT_TYPE;',
    '',
    '    const variantStyles = {',
    '      filled: {',
    '        backgroundColor: "var(--prism-color-primary, #0057d9)",',
    '        borderColor: "transparent",',
    '        color: "var(--prism-color-on-primary, #ffffff)"',
    '      },',
    '      outlined: {',
    '        backgroundColor: "transparent",',
    '        borderColor: "var(--prism-color-outline, #74777f)",',
    '        color: "var(--prism-color-primary, #0057d9)"',
    '      },',
    '      tonal: {',
    '        backgroundColor: "var(--prism-color-secondary-container, #d6e3ff)",',
    '        borderColor: "transparent",',
    '        color: "var(--prism-color-on-secondary-container, #091b36)"',
    '      },',
    '      text: {',
    '        backgroundColor: "transparent",',
    '        borderColor: "transparent",',
    '        color: "var(--prism-color-primary, #0057d9)"',
    '      }',
    '    };',
    '',
    '    const sizeStyles = {',
    '      small: {',
    '        minHeight: "2rem",',
    '        paddingInline: "0.75rem",',
    '        typographySize: "small"',
    '      },',
    '      medium: {',
    '        minHeight: "2.5rem",',
    '        paddingInline: "1rem",',
    '        typographySize: "medium"',
    '      },',
    '      large: {',
    '        minHeight: "3rem",',
    '        paddingInline: "1.25rem",',
    '        typographySize: "large"',
    '      }',
    '    };',
    '',
    '    const variantStyle = variantStyles[resolvedVariant];',
    '    const sizeStyle = sizeStyles[resolvedSize];',
    '',
    '    control.type = resolvedType;',
    '    control.disabled = this.hasAttribute("disabled");',
    '    control.style.backgroundColor = variantStyle.backgroundColor;',
    '    control.style.borderColor = variantStyle.borderColor;',
    '    control.style.color = variantStyle.color;',
    '    control.style.minHeight = sizeStyle.minHeight;',
    '    control.style.paddingInline = sizeStyle.paddingInline;',
    '',
    '    label.style.fontFamily = `var(--prism-typography-label-${sizeStyle.typographySize}-font-family)`;',
    '    label.style.fontSize = `var(--prism-typography-label-${sizeStyle.typographySize}-font-size)`;',
    '    label.style.fontWeight = `var(--prism-typography-label-${sizeStyle.typographySize}-font-weight)`;',
    '    label.style.letterSpacing = `var(--prism-typography-label-${sizeStyle.typographySize}-letter-spacing)`;',
    '    label.style.lineHeight = `var(--prism-typography-label-${sizeStyle.typographySize}-line-height)`;',
    '  }',
    '}',
    '',
    `export function register${blueprint.className}() {`,
    '  if (typeof customElements === "undefined") {',
    '    return;',
    '  }',
    '',
    `  if (!customElements.get(${JSON.stringify(blueprint.tagName)})) {`,
    `    customElements.define(${JSON.stringify(blueprint.tagName)}, ${blueprint.className});`,
    '  }',
    '}',
    ''
  ].join('\n');
}

