function typographySource(blueprint: ComponentBlueprint): string {
  const variantAttribute = findAttribute(blueprint, 'variant');
  const sizeAttribute = findAttribute(blueprint, 'size');
  const asAttribute = findAttribute(blueprint, 'as');

  const variants = enumValues(variantAttribute);
  const sizes = enumValues(sizeAttribute);
  const tagNames = enumValues(asAttribute);

  const defaultVariant = enumDefault(variantAttribute);
  const defaultSize = enumDefault(sizeAttribute);
  const defaultTagName = enumDefault(asAttribute);

  const styleHooks = renderStyleHooks(blueprint, [
    { selector: ':host', target: 'host' },
    { selector: '.container', target: 'container' },
    { selector: '.text', target: 'text' }
  ]);

  return [
    ...FILE_HEADER_LINES,
    'const PrismHTMLElement = globalThis.HTMLElement ?? class {};',
    `const TYPOGRAPHY_VARIANTS = Object.freeze(${renderArray(variants)});`,
    `const TYPOGRAPHY_SIZES = Object.freeze(${renderArray(sizes)});`,
    `const TYPOGRAPHY_TAG_NAMES = Object.freeze(${renderArray(tagNames)});`,
    `const DEFAULT_VARIANT = ${JSON.stringify(defaultVariant)};`,
    `const DEFAULT_SIZE = ${JSON.stringify(defaultSize)};`,
    `const DEFAULT_TAG_NAME = ${JSON.stringify(defaultTagName)};`,
    '',
    `export const ${blueprint.className}Slots = Object.freeze(${renderArray(blueprint.slots.map((slot) => slot.name))});`,
    `export const ${blueprint.className}Parts = Object.freeze(${renderArray(blueprint.parts.map((part) => part.name))});`,
    '',
    `export class ${blueprint.className} extends PrismHTMLElement {`,
    `  static tagName = ${JSON.stringify(blueprint.tagName)};`,
    `  static observedAttributes = Object.freeze(${renderArray(
      blueprint.attributes.map((attribute) => attribute.name).sort((left, right) => left.localeCompare(right))
    )});`,
    '',
    '  #text = null;',
    '  #textTagName = "";',
    '',
    '  constructor() {',
    '    super();',
    '    if (typeof this.attachShadow === "function" && !this.shadowRoot) {',
    '      this.attachShadow({ mode: "open" });',
    '    }',
    '  }',
    '',
    '  connectedCallback() {',
    '    this.#render();',
    '    this.#sync();',
    '  }',
    '',
    '  attributeChangedCallback() {',
    '    this.#sync();',
    '  }',
    '',
    '  #render() {',
    '    if (!this.shadowRoot || this.shadowRoot.childNodes.length > 0) {',
    '      return;',
    '    }',
    '',
    '    this.shadowRoot.innerHTML = `',
    '<style>',
    ':host {',
    '  display: block;',
    '}',
    '',
    '.container {',
    '  display: contents;',
    '}',
    '',
    '.text {',
    '  margin: 0;',
    '}',
    '',
    styleHooks,
    '</style>',
    '<span class="container"></span>',
    '`;',
    '  }',
    '',
    '  #ensureText(tagName) {',
    '    if (!this.shadowRoot || typeof document === "undefined") {',
    '      return null;',
    '    }',
    '',
    '    const container = this.shadowRoot.querySelector(".container");',
    '    if (!container) {',
    '      return null;',
    '    }',
    '',
    '    if (this.#text && this.#textTagName === tagName) {',
    '      return this.#text;',
    '    }',
    '',
    '    const text = document.createElement(tagName);',
    '    text.className = "text";',
    '    text.setAttribute("part", "text");',
    '    text.innerHTML = "<slot></slot>";',
    '    container.replaceChildren(text);',
    '',
    '    this.#text = text;',
    '    this.#textTagName = tagName;',
    '    return text;',
    '  }',
    '',
    '  #sync() {',
    '    const variant = this.getAttribute("variant");',
    '    const size = this.getAttribute("size");',
    '    const as = this.getAttribute("as");',
    '',
    '    const resolvedVariant = TYPOGRAPHY_VARIANTS.includes(variant ?? "") ? variant : DEFAULT_VARIANT;',
    '    const resolvedSize = TYPOGRAPHY_SIZES.includes(size ?? "") ? size : DEFAULT_SIZE;',
    '    const resolvedTagName = TYPOGRAPHY_TAG_NAMES.includes(as ?? "") ? as : DEFAULT_TAG_NAME;',
    '',
    '    const text = this.#ensureText(resolvedTagName);',
    '    if (!text) {',
    '      return;',
    '    }',
    '',
    '    text.style.fontFamily = `var(--prism-typography-${resolvedVariant}-${resolvedSize}-font-family)`;',
    '    text.style.fontSize = `var(--prism-typography-${resolvedVariant}-${resolvedSize}-font-size)`;',
    '    text.style.fontWeight = `var(--prism-typography-${resolvedVariant}-${resolvedSize}-font-weight)`;',
    '    text.style.letterSpacing = `var(--prism-typography-${resolvedVariant}-${resolvedSize}-letter-spacing)`;',
    '    text.style.lineHeight = `var(--prism-typography-${resolvedVariant}-${resolvedSize}-line-height)`;',
    '  }',
    '}',
    '',
    `export function register${blueprint.className}() {`,
    '  if (typeof customElements === "undefined") {',
    '    return;',
    '  }',
    '',
    `  if (!customElements.get(${JSON.stringify(blueprint.tagName)})) {`,
    `    customElements.define(${JSON.stringify(blueprint.tagName)}, ${blueprint.className});`,
    '  }',
    '}',
    ''
  ].join('\n');
}

function surfaceSource(blueprint: ComponentBlueprint): string {
  const toneAttribute = findAttribute(blueprint, 'tone');
  const elevationAttribute = findAttribute(blueprint, 'elevation');

  const tones = enumValues(toneAttribute);
  const elevations = enumValues(elevationAttribute);

  const defaultTone = enumDefault(toneAttribute);
  const defaultElevation = enumDefault(elevationAttribute);

  const styleHooks = renderStyleHooks(blueprint, [
    { selector: ':host', target: 'host' },
    { selector: '.container', target: 'container' },
    { selector: '.header', target: 'header' },
    { selector: '.body', target: 'body' },
    { selector: '.footer', target: 'footer' }
  ]);

  return [
    ...FILE_HEADER_LINES,
    'const PrismHTMLElement = globalThis.HTMLElement ?? class {};',
    `const SURFACE_TONES = Object.freeze(${renderArray(tones)});`,
    `const SURFACE_ELEVATIONS = Object.freeze(${renderArray(elevations)});`,
    `const DEFAULT_TONE = ${JSON.stringify(defaultTone)};`,
    `const DEFAULT_ELEVATION = ${JSON.stringify(defaultElevation)};`,
    '',
    `export const ${blueprint.className}Slots = Object.freeze(${renderArray(blueprint.slots.map((slot) => slot.name))});`,
    `export const ${blueprint.className}Parts = Object.freeze(${renderArray(blueprint.parts.map((part) => part.name))});`,
    '',
    `export class ${blueprint.className} extends PrismHTMLElement {`,
    `  static tagName = ${JSON.stringify(blueprint.tagName)};`,
    `  static observedAttributes = Object.freeze(${renderArray(
      blueprint.attributes.map((attribute) => attribute.name).sort((left, right) => left.localeCompare(right))
    )});`,
    '',
    '  #container = null;',
    '  #header = null;',
    '  #footer = null;',
    '  #headerSlot = null;',
    '  #footerSlot = null;',
    '',
    '  constructor() {',
    '    super();',
    '    if (typeof this.attachShadow === "function" && !this.shadowRoot) {',
    '      this.attachShadow({ mode: "open" });',
    '    }',
    '  }',
    '',
    '  connectedCallback() {',
    '    this.#render();',
    '    this.#sync();',
    '  }',
    '',
    '  attributeChangedCallback() {',
    '    this.#sync();',
    '  }',
    '',
    '  #render() {',
    '    if (!this.shadowRoot || this.shadowRoot.childNodes.length > 0) {',
    '      return;',
    '    }',
    '',
    '    this.shadowRoot.innerHTML = `',
    '<style>',
    ':host {',
    '  display: block;',
    '}',
    '',
    '.container {',
    '  border: 1px solid transparent;',
    '  box-shadow: 0 calc(var(--prism-surface-elevation-factor, 0) * 1px) calc(var(--prism-surface-elevation-factor, 0) * 4px) rgba(0, 0, 0, 0.24);',
    '  display: grid;',
    '  gap: 1rem;',
    '  padding: 1rem;',
    '  transition: box-shadow 120ms ease, transform 120ms ease;',
    '}',
    '',
    ':host([interactive]) .container {',
    '  cursor: pointer;',
    '}',
    '',
    ':host([interactive]) .container:hover {',
    '  box-shadow: 0 calc(var(--prism-surface-elevation-factor, 0) * 1.5px) calc(var(--prism-surface-elevation-factor, 0) * 5px) rgba(0, 0, 0, 0.24);',
    '  transform: translateY(-1px);',
    '}',
    '',
    '.header,',
    '.footer {',
    '  display: block;',
    '}',
    '',
    '.header[hidden],',
    '.footer[hidden] {',
    '  display: none;',
    '}',
    '',
    '.body {',
    '  display: block;',
    '}',
    '',
    styleHooks,
    '</style>',
    '<section class="container" part="container">',
    '  <header class="header" part="header" hidden><slot name="header"></slot></header>',
    '  <div class="body" part="body"><slot></slot></div>',
    '  <footer class="footer" part="footer" hidden><slot name="footer"></slot></footer>',
    '</section>',
    '`;',
    '',
    '    this.#container = this.shadowRoot.querySelector(".container");',
    '    this.#header = this.shadowRoot.querySelector(".header");',
    '    this.#footer = this.shadowRoot.querySelector(".footer");',
    '    this.#headerSlot = this.shadowRoot.querySelector("slot[name=\\\"header\\\"]");',
    '    this.#footerSlot = this.shadowRoot.querySelector("slot[name=\\\"footer\\\"]");',
    '    this.#headerSlot?.addEventListener("slotchange", () => this.#syncSlotVisibility());',
    '    this.#footerSlot?.addEventListener("slotchange", () => this.#syncSlotVisibility());',
    '  }',
    '',
    '  #syncSlotVisibility() {',
    '    const hasHeader = Boolean(this.#headerSlot?.assignedNodes({ flatten: true }).length);',
    '    const hasFooter = Boolean(this.#footerSlot?.assignedNodes({ flatten: true }).length);',
    '',
    '    this.#header?.toggleAttribute("hidden", !hasHeader);',
    '    this.#footer?.toggleAttribute("hidden", !hasFooter);',
    '  }',
    '',
    '  #sync() {',
    '    const container = this.#container;',
    '    if (!container) {',
    '      return;',
    '    }',
    '',
    '    const tone = this.getAttribute("tone");',
    '    const elevation = this.getAttribute("elevation");',
    '',
    '    const resolvedTone = SURFACE_TONES.includes(tone ?? "") ? tone : DEFAULT_TONE;',
    '    const resolvedElevation = SURFACE_ELEVATIONS.includes(elevation ?? "") ? elevation : DEFAULT_ELEVATION;',
    '',
    '    const toneStyles = {',
    '      default: {',
    '        backgroundColor: "var(--prism-color-surface, #fbf8ff)",',
    '        color: "var(--prism-color-on-surface, #1a1b1f)"',
    '      },',
    '      "container-low": {',
    '        backgroundColor: "var(--prism-color-surface-container-low, #f5f3fa)",',
    '        color: "var(--prism-color-on-surface, #1a1b1f)"',
    '      },',
    '      "container-high": {',
    '        backgroundColor: "var(--prism-color-surface-container-high, #eae7ef)",',
    '        color: "var(--prism-color-on-surface, #1a1b1f)"',
    '      },',
    '      inverse: {',
    '        backgroundColor: "var(--prism-color-inverse-surface, #2f3035)",',
    '        color: "var(--prism-color-inverse-on-surface, #f1eff6)"',
    '      }',
    '    };',
    '',
    '    const toneStyle = toneStyles[resolvedTone];',
    '    container.style.backgroundColor = toneStyle.backgroundColor;',
    '    container.style.color = toneStyle.color;',
    '    container.style.setProperty(',
    '      "--prism-surface-elevation-factor",',
    '      `var(--prism-elevation-${resolvedElevation}, 0)`',
    '    );',
    '',
    '    this.#syncSlotVisibility();',
    '  }',
    '}',
    '',
    `export function register${blueprint.className}() {`,
    '  if (typeof customElements === "undefined") {',
    '    return;',
    '  }',
    '',
    `  if (!customElements.get(${JSON.stringify(blueprint.tagName)})) {`,
    `    customElements.define(${JSON.stringify(blueprint.tagName)}, ${blueprint.className});`,
    '  }',
    '}',
    ''
  ].join('\n');
}

function generateSourceForBlueprint(blueprint: ComponentBlueprint): string {
  switch (blueprint.templateKind) {
    case 'button':
      return buttonSource(blueprint);
    case 'icon-button':
      return iconButtonSource(blueprint);
    case 'typography':
      return typographySource(blueprint);
    case 'surface':
      return surfaceSource(blueprint);
    default:
      throw new Error(`Unsupported template kind "${blueprint.templateKind}".`);
  }
}

export function artifactFileNameForBlueprint(blueprint: ComponentBlueprint): string {
  return `${blueprint.tagName}.component.js`;
}

export function generateComponentArtifact(blueprint: ComponentBlueprint): GeneratedComponentArtifact {
  return {
    componentId: blueprint.componentId,
    tagName: blueprint.tagName,
    artifactFileName: artifactFileNameForBlueprint(blueprint),
    source: generateSourceForBlueprint(blueprint)
  };
}

export function generateComponentArtifacts(
  blueprints: readonly ComponentBlueprint[] = componentBlueprints
): readonly GeneratedComponentArtifact[] {
  return [...blueprints]
    .sort((left, right) => left.componentId.localeCompare(right.componentId))
    .map((blueprint) => generateComponentArtifact(blueprint));
}
